mapper.select:

/* selectWorkerHistoryCount - Ji-Seob Lee */

SELECT
    COUNT(*) AS CNT

FROM SCA101 C
LEFT JOIN SCA100 D /* 종사자 */ ON D.ENFSN_NO = C.ENFSN_NO
LEFT JOIN SAA000 E /* 통합기관 */ ON E.INST_NO = D.OGDP_INST_NO






        AND C.DATAA_CHG_SE_CD = #{DATAA_CHG_SE_CD}




        AND C.SXDC_SE_CD = #{SXDC_SE_CD}




        AND C.FLNM_ENCPT = ENC_B64(#{FLNM_ENCPT})




        AND C.EML_ADDR_ENCPT = ENC_B64(#{EML_ADDR_ENCPT})




        AND C.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}




        AND C.MDFCN_DT >= TO_DATE(#{START_DATE} || '000000', 'YYYYMMDDHH24MISS')




        AND C.MDFCN_DT <= TO_DATE(#{END_DATE} || '235959', 'YYYYMMDDHH24MISS')




        AND E.INST_NM LIKE '%' || #{INST_NM} || '%'




        AND C.LAST_MDFR_ID LIKE '%' || #{WORKER} || '%'




        AND C.ENFSN_NO = #{ENFSN_NO}

/* selectWorkerHistory - Ji-Seob Lee */
SELECT C.ENFSN_NO, TO_CHAR(C.MDFCN_DT, 'YYYY-MM-DD HH24:MI') AS MDFCN_DT, C.UNT_TASKWK_SE_CD, C.DATAA_CHG_SE_CD, C.ENFSN_ROLE_SE_CD, C.INDV_IDNTFC_NO, C.QLFC_SE_CD, C.DEL_YN, DEC_B64(C.FLNM_ENCPT) AS FLNM_ENCPT, C.BRTH_YMD, C.SXDC_SE_CD, C.WRD_TELNO, DEC_B64(C.MBL_TELNO_ENCPT) AS MBL_TELNO_ENCPT, DEC_B64(C.EML_ADDR_ENCPT) AS EML_ADDR_ENCPT, C.SNS_SE_CD, DEC_B64(C.MSNGR_ID_ENCPT) AS MSNGR_ID_ENCPT, C.QLFC_INFO_MNG_NO, C.NCKN_NM, C.ATFINO, C.CNSLTNT_USE_VCATN_DAYCNT, C.CNSLTNT_USE_PSBLTY_YRYC_DAYCNT, C.TASKWK_TYPE_INST_NO, C.SRASH_WRT_YN, C.SRASH_WRT_BGNG_YMD, C.SRASH_WRT_END_YMD, C.DSCSN_PRFMNC_HSTR_BGNG_YMD, C.DSCSN_PRFMNC_HSTR_END_YMD, C.VCATN_DAYCNT, C.ERP_EMPLA_NO, C.OGDP_INST_NO, (SELECT D.INST_NM FROM SAA000 D WHERE D.INST_NO = C.OGDP_INST_NO) AS OGDP_INST_NM, C.OGDP_DEPT_CD, (SELECT D.DEPT_NM FROM SAA300 D WHERE D.INST_NO = C.OGDP_INST_NO AND D.DEPT_CD = C.OGDP_DEPT_CD) AS OGDP_DEPT_NM, C.JBPS_NM, C.ISTDR_YN, C.JNCMP_YMD, C.RETIRE_YMD, C.GITPLE_ID, C.UNIVER_ESNTAL_IDFR_NO, C.ABILIT_MNG_MNGR_YN, C.ORGNL_ENFSN_NO, C.FRST_RGTR_ID, TO_CHAR(C.FRST_REG_DT, 'YYYY-MM-DD HH24:MI:SS') AS FRST_REG_DT, C.LAST_MDFR_ID, TO_CHAR(C.LAST_MDFCN_DT, 'YYYY-MM-DD HH24:MI:SS') AS LAST_MDFCN_DT, NVL(C.LAST_MDFR_ID, C.FRST_RGTR_ID) AS WORKER, E.INST_NM
FROM SCA101 C LEFT JOIN SCA100 D /* 종사자 */ ON D.ENFSN_NO = C.ENFSN_NO LEFT JOIN SAA000 E /* 통합기관 */ ON E.INST_NO = D.OGDP_INST_NO
AND C.DATAA_CHG_SE_CD = #{DATAA_CHG_SE_CD}
AND C.SXDC_SE_CD = #{SXDC_SE_CD}
AND C.FLNM_ENCPT = ENC_B64(#{FLNM_ENCPT})
AND C.EML_ADDR_ENCPT = ENC_B64(#{EML_ADDR_ENCPT})
AND C.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND C.MDFCN_DT >= TO_DATE(#{START_DATE} || '000000', 'YYYYMMDDHH24MISS')
AND C.MDFCN_DT <= TO_DATE(#{END_DATE} || '235959', 'YYYYMMDDHH24MISS')
AND E.INST_NM LIKE '%' || #{INST_NM} || '%'
AND C.LAST_MDFR_ID LIKE '%' || #{WORKER} || '%'
AND C.ENFSN_NO = #{ENFSN_NO}
ORDER BY MDFCN_DT DESC
OFFSET #{OFFSET_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY


/* selectYouthGuardianHistoryCount - Ji-Seob Lee */

SELECT
    COUNT(*) AS CNT

FROM SCA201






        AND DATAA_CHG_SE_CD = #{DATAA_CHG_SE_CD}




        AND YNGBGS_PRTCR_SE_CD = #{YNGBGS_PRTCR_SE_CD}




        AND FLNM_ENCPT = ENC_B64(#{FLNM_ENCPT})




        AND SXDC_SE_CD = #{SXDC_SE_CD}




        AND RGN_CD = #{RGN_CD}




        AND MDFCN_DT >= TO_DATE(#{START_DATE} || '000000', 'YYYYMMDDHH24MISS')




        AND MDFCN_DT <= TO_DATE(#{END_DATE} || '235959', 'YYYYMMDDHH24MISS')




        AND LAST_MDFR_ID LIKE '%' || #{WORKER} || '%'

/* selectYouthGuardianHistory - Ji-Seob Lee */
SELECT YNGBGS_PRTCR_NO, TO_CHAR(MDFCN_DT, 'YYYY-MM-DD HH24:MI') AS MDFCN_DT, DATAA_CHG_SE_CD, INDV_IDNTFC_NO, YNGBGS_PRTCR_SE_CD, DEC_B64(FLNM_ENCPT) AS FLNM_ENCPT, SXDC_SE_CD, BRTH_YMD, WRD_TELNO, DEC_B64(MBL_TELNO_ENCPT) AS MBL_TELNO_ENCPT, DEC_B64(EML_ADDR_ENCPT) AS EML_ADDR_ENCPT, ZIP, PST_ADDR, DADDR, DEC_B64(STTY_AGT_NM_ENCPT) AS STTY_AGT_NM_ENCPT, STTY_AGT_CTTPC_TELNO, OCCP_NM, RGN_CD, INFO_PVSN_AGRE_YN1, INFO_PVSN_AGRE_YN2, DEL_YN, QLFC_INFO_MNG_NO, DEC_B64(PSPT_ENG_FLNM_ENCPT) AS PSPT_ENG_FLNM_ENCPT, TRPR_BCRN_TYPE_SE_CD, TRPR_BCRN_TYPE_RM_NM, NLTY_NTN_SE_CD, ENTCNY_YMD, BRTH_NTN_SE_CD, GROWTH_NTN_SE_CD, VISA_TYPE_SE_CD, HANAWO_PENU_NO, RELGN_SE_CD, ORGNL_YNGBGS_PRTCR_NO, FRST_RGTR_ID, TO_CHAR(FRST_REG_DT, 'YYYY-MM-DD HH24:MI:SS') AS FRST_REG_DT, LAST_MDFR_ID, TO_CHAR(LAST_MDFCN_DT, 'YYYY-MM-DD HH24:MI:SS') AS LAST_MDFCN_DT, NVL(LAST_MDFR_ID, FRST_RGTR_ID) AS WORKER FROM SCA201
AND DATAA_CHG_SE_CD = #{DATAA_CHG_SE_CD}
AND YNGBGS_PRTCR_SE_CD = #{YNGBGS_PRTCR_SE_CD}
AND FLNM_ENCPT = ENC_B64(#{FLNM_ENCPT})
AND SXDC_SE_CD = #{SXDC_SE_CD}
AND RGN_CD = #{RGN_CD}
AND MDFCN_DT >= TO_DATE(#{START_DATE} || '000000', 'YYYYMMDDHH24MISS')
AND MDFCN_DT <= TO_DATE(#{END_DATE} || '235959', 'YYYYMMDDHH24MISS')
AND LAST_MDFR_ID LIKE '%' || #{WORKER} || '%'
ORDER BY MDFCN_DT DESC
OFFSET #{OFFSET_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY


/* selectPersonalInfoHistoryCount - Ji-Seob Lee */

SELECT
    COUNT(*) AS CNT

FROM SCA301






        AND DATAA_CHG_SE_CD = #{DATAA_CHG_SE_CD}




        AND SXDC_SE_CD = #{SXDC_SE_CD}




        AND FLNM_ENCPT = ENC_B64(#{FLNM_ENCPT})




        AND PST_ADDR LIKE '%' || #{PST_ADDR} || '%'




        AND LAST_ACBG_SE_CD = #{LAST_ACBG_SE_CD}




        AND MDFCN_DT >= TO_DATE(#{START_DATE} || '000000', 'YYYYMMDDHH24MISS')




        AND MDFCN_DT <= TO_DATE(#{END_DATE} || '235959', 'YYYYMMDDHH24MISS')




        AND LAST_MDFR_ID LIKE '%' || #{WORKER} || '%'




        AND INDV_IDNTFC_NO = #{INDV_IDNTFC_NO}

/* selectPersonalInfoHistory - Ji-Seob Lee */
SELECT INDV_IDNTFC_NO, TO_CHAR(MDFCN_DT, 'YYYY-MM-DD HH24:MI') AS MDFCN_DT, DATAA_CHG_SE_CD, DEC_B64(FLNM_ENCPT) AS FLNM_ENCPT, DEC_B64(RRNO_ENCPT) AS RRNO_ENCPT, BRTH_YMD, SXDC_SE_CD, MRG_YN, LAST_ACBG_SE_CD, WRD_TELNO, DEC_B64(MBL_TELNO_ENCPT) AS MBL_TELNO_ENCPT, DEC_B64(EML_ADDR_ENCPT) AS EML_ADDR_ENCPT, SNS_SE_CD, DEC_B64(MSNGR_ID_ENCPT) AS MSNGR_ID_ENCPT, ZIP, PST_ADDR, DADDR, RGN_CD, PRVC_DSCD_PRNMNT_YMD, PRVC_DSCD_YMD, OFCERT_ME_CERT_DN_VALUE_CN, FICE_ME_CERT_DN_VALUE_CN, PIN_ME_CERT_DN_VALUE_CN, MOPH_ME_CERT_DN_VALUE_CN, SNS_SIMPC_CERT_DN_VALUE_CN, ENFSN_NO, INST_NO, CHG_CS_CN, ORGNL_INDV_IDNTFC_NO, FRST_RGTR_ID, TO_CHAR(FRST_REG_DT, 'YYYY-MM-DD HH24:MI:SS') AS FRST_REG_DT, LAST_MDFR_ID, TO_CHAR(LAST_MDFCN_DT, 'YYYY-MM-DD HH24:MI:SS') AS LAST_MDFCN_DT, NVL(LAST_MDFR_ID, FRST_RGTR_ID) AS WORKER FROM SCA301
AND DATAA_CHG_SE_CD = #{DATAA_CHG_SE_CD}
AND SXDC_SE_CD = #{SXDC_SE_CD}
AND FLNM_ENCPT = ENC_B64(#{FLNM_ENCPT})
AND PST_ADDR LIKE '%' || #{PST_ADDR} || '%'
AND LAST_ACBG_SE_CD = #{LAST_ACBG_SE_CD}
AND MDFCN_DT >= TO_DATE(#{START_DATE} || '000000', 'YYYYMMDDHH24MISS')
AND MDFCN_DT <= TO_DATE(#{END_DATE} || '235959', 'YYYYMMDDHH24MISS')
AND LAST_MDFR_ID LIKE '%' || #{WORKER} || '%'
AND INDV_IDNTFC_NO = #{INDV_IDNTFC_NO}
ORDER BY MDFCN_DT DESC
OFFSET #{OFFSET_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY
